import { type ClassValue, clsx } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

// tw-merge only knows stock sizes and misreads these as text COLOR group, so size and color in one cn() collide and one is dropped.
const textScale = [
  "micro",
  "caption",
  "label",
  "body",
  "body-lg",
  "heading-1",
  "heading-2",
  "heading-3",
  "heading-4",
  // legacy aliases kept until their call sites migrate to canonical rungs above
  "meta",
  "title-sm",
  "title-md",
  "title-lg",
  "display",
];

// unregistered, tw-merge reads these as shadow COLOR and lets them ride alongside later box-shadow util, so skin's override loses by CSS order instead of argument order
const shadowScale = ["pop", "soft", "modal"];

const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [{ text: textScale }],
      shadow: [{ shadow: shadowScale }],
    },
  },
  // stock Tailwind bakes line-height into `text-*`, so twMerge lets font-size clear preceding `leading-*`; this scale is size-only, so that conflict must go
  override: {
    conflictingClassGroups: {
      "font-size": [],
    },
  },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import type { ReactNode } from "react";
import type { ButtonTone, ButtonVariant, ControlEffect, SelectionIndicator } from "./contracts";
import { skin } from "./skin.config";

type StatelessPart = Record<never, never>;
export type SkinAdornmentContexts = {
  button: { layer: { variant: ButtonVariant; tone: ButtonTone } };
  "chat-layout": { titlebar: StatelessPart };
  "chat-thought": { details: StatelessPart };
  dialog: { titlebar: StatelessPart };
  "chat-composer": { "send-layer": { sendCount: number } };
};

export type SkinAdornmentScope = keyof SkinAdornmentContexts;
export type SkinAdornmentPart<Scope extends SkinAdornmentScope> = keyof SkinAdornmentContexts[Scope];

type AdornmentEntry<Ctx> = ReactNode | ((ctx: Ctx) => ReactNode);

export type ControlUiSkin = {
  /** Scopes theme.css/skin.css via data-skin; components stamp it on portal containers. */
  id: string;
  /** Stamps data-motion="reduced", collapsing --duration-* to 0ms. Never `animation:none` — ripple cleanup still needs `animationend` to fire. */
  motion?: "reduced";
  /** Locks skin to one scheme; page's .dark class must then follow it, since Shiki, native color-scheme, and dark: utilities key off .dark, not skin tokens. Undefined = adaptive, both blocks authored. */
  colorScheme?: "light" | "dark";
  /** Geometry, not slot restyle — padding, gap, rounding, and shadow across sidebar gap/container/inner. explicit `variant` prop wins; undefined keeps "sidebar". */
  sidebarLayout?: SidebarLayout;
  /** App-wide choice: sidebars and trees all glide or none do. Explicit `indicator` still wins; undefined also skips highlight engine's lazy chunk. */
  indicators?: { sidebar?: SelectionIndicator; tree?: SelectionIndicator };
  /** Any CSS length. Seeds --sidebar-width; caller's own value still wins. Undefined keeps shadcn's 16rem. */
  sidebarWidth?: string;
  /** effects.css keys off data-effects ancestor attribute. top-shine is CSS-only; ripple needs runtime's document pointer listener. */
  effects?: ControlEffect[];
  adornments?: {
    [Scope in SkinAdornmentScope]?: {
      [Part in SkinAdornmentPart<Scope>]?: AdornmentEntry<SkinAdornmentContexts[Scope][Part]>;
    };
  };
};

export type SidebarLayout = "sidebar" | "floating" | "inset";

/** Read at render time so getter-based configs stay live. Portals stamp it on their positioner, which lands outside any token-scoped ancestor. */
export function activeSkin(): ControlUiSkin {
  return skin;
}

export function skinId(): string {
  return skin.id;
}

/** Sidebar falls back: variant prop → this → "sidebar". */
export function skinSidebarLayout(): SidebarLayout | undefined {
  return skin.sidebarLayout;
}

/** Component falls back: indicator prop → this → "none". */
export function skinIndicator(component: "sidebar" | "tree"): SelectionIndicator | undefined {
  return skin.indicators?.[component];
}

/** SidebarProvider seeds --sidebar-width from this; caller-provided value still wins. */
export function skinSidebarWidth(): string | undefined {
  return skin.sidebarWidth;
}

/** Portals stamp result next to data-skin; ControlEffectsRuntime mirrors it on <html>. */
export function skinEffects(): string | undefined {
  const effects = skin.effects;
  return effects && effects.length > 0 ? effects.join(" ") : undefined;
}

import { cva } from "class-variance-authority";

export const controlSize = cva("", {
  variants: {
    size: {
      xs: "h-[var(--control-h-xs)] gap-1 px-[calc(var(--padding-x)*0.6)] text-caption",
      sm: "h-[var(--control-h-sm)] gap-1.5 px-[calc(var(--padding-x)*0.75)] text-label",
      md: "h-[var(--control-h-md)] gap-1.5 px-[var(--padding-x)] text-body",
      lg: "h-[var(--control-h-lg)] gap-2 px-[calc(var(--padding-x)*1.25)] text-body",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

/* Every utility here reads theme tokens, so a theme rewrite restyles the effects too. Tailwind only emits an @utility that scanned source references. */

/* apply to a sized block */
@utility shimmer {
  background-image: linear-gradient(
    100deg,
    var(--muted) 30%,
    oklch(from var(--muted-foreground) l c h / 0.25) 50%,
    var(--muted) 70%
  );
  background-size: 220% 100%;
  animation: shimmer calc(var(--duration-slow) * 5) var(--ease-standard) infinite;

  /* Reduced motion: hold resting gradient (infinite animation ignores 0ms collapse, must still explicitly) under OS pref + motion kill-switch attribute. */
  @media (prefers-reduced-motion: reduce) {
    animation: none;
  }
  :where([data-motion="reduced"]) & {
    animation: none;
  }
}

/* shimmer-text — same sweep clipped to text ("AI is generating" treatment); subtle --muted-foreground↔--foreground stops keep it readable. */
@utility shimmer-text {
  background-image: linear-gradient(
    100deg,
    var(--muted-foreground) 35%,
    var(--foreground) 50%,
    var(--muted-foreground) 65%
  );
  background-size: 220% 100%;
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
  animation: shimmer calc(var(--duration-slow) * 6) var(--ease-standard) infinite;

  /* Reduced motion: static muted-foreground text, no sweep — stilled under OS pref + motion kill-switch (infinite animation ignores 0ms tempo). */
  @media (prefers-reduced-motion: reduce) {
    animation: none;
  }
  :where([data-motion="reduced"]) & {
    animation: none;
  }
}

@keyframes shimmer {
  from {
    background-position: 180% 0;
  }
  to {
    background-position: -80% 0;
  }
}

/* halftone — "media is being generated" fill for a box whose final size is already reserved (image gen placeholder).
 * The lattice never moves and the mask is a fixed corner-to-corner fade; the dots themselves breathe, which is what
 * reads as halftone. A travelling mask was tried and rejected: it leaves the box blank for most of the cycle.
 * Registration required to interpolate the radius — browsers without @property hold the resting dot, never a broken box.
 * Token-parameterized (pack re-values, no fork): --halftone-color, -dot (resting radius), -gap (lattice pitch). */
@property --halftone-pulse {
  syntax: "<number>";
  inherits: false;
  initial-value: 1;
}

@utility halftone {
  --halftone-radius: calc(var(--halftone-dot, 1.4px) * var(--halftone-pulse));
  background-image: radial-gradient(
    circle at center,
    var(--halftone-color, oklch(from var(--muted-foreground) l c h / 0.7)) var(--halftone-radius),
    transparent calc(var(--halftone-radius) + 0.4px)
  );
  background-size: var(--halftone-gap, 11px) var(--halftone-gap, 11px);
  -webkit-mask-image: linear-gradient(to top left, transparent 0%, oklch(0 0 0) 30%, oklch(0 0 0) 70%, transparent 100%);
  mask-image: linear-gradient(to top left, transparent 0%, oklch(0 0 0) 30%, oklch(0 0 0) 70%, transparent 100%);
  -webkit-mask-size: 100% 100%;
  mask-size: 100% 100%;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  animation: aui-halftone calc(var(--duration-slow) * 6) var(--ease-standard) infinite;

  /* Reduced motion: dots hold at their resting radius — still a legible placeholder, just no breathing. */
  @media (prefers-reduced-motion: reduce) {
    animation: none;
  }
  :where([data-motion="reduced"]) & {
    animation: none;
  }
}

@keyframes aui-halftone {
  0%,
  100% {
    --halftone-pulse: 0.55;
  }
  50% {
    --halftone-pulse: 1.5;
  }
}

/* progress-sweep — retro alt to shimmer-text: hard-edged --primary blocks marching L-to-R, clipped to text (Minecraft/Windows XP bar).
 * Token-parameterized (pack re-values, no fork): --progress-sweep-color, -block/-step (lit width/repeat period, gap=step−block), -fade (dim gap alpha).
 * text-shadow cleared — glyph shadow would paint over transparent fill (same reason as the fill reset). */
@utility progress-sweep {
  background-image: repeating-linear-gradient(
    90deg,
    var(--progress-sweep-color, var(--primary)) 0 var(--progress-sweep-block, 8px),
    oklch(from var(--progress-sweep-color, var(--primary)) l c h / var(--progress-sweep-fade, 0.4))
      var(--progress-sweep-block, 8px) var(--progress-sweep-step, 12px)
  );
  background-size: 200% 100%;
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
  text-shadow: none;
  animation: aui-progress-sweep calc(var(--duration-slow) * 12) linear infinite;

  /* Reduced motion: static blocks, no march — stilled under OS pref + motion kill-switch (infinite animation ignores 0ms tempo). */
  @media (prefers-reduced-motion: reduce) {
    animation: none;
  }
  :where([data-motion="reduced"]) & {
    animation: none;
  }
}

@keyframes aui-progress-sweep {
  from {
    background-position: 0 0;
  }
  to {
    background-position: -200% 0;
  }
