    0 calc(3.4px * var(--shadow-size) * var(--shadow-modal-multiplier) * var(--shadow-y))
      calc(7px * var(--shadow-size) * var(--shadow-modal-multiplier))
      calc(-1.6px * var(--shadow-size) * var(--shadow-modal-multiplier))
      oklch(from var(--shadow-color) l c h / calc(0.07 * var(--shadow-opacity))),
    0 calc(7px * var(--shadow-size) * var(--shadow-modal-multiplier) * var(--shadow-y))
      calc(16px * var(--shadow-size) * var(--shadow-modal-multiplier))
      calc(-3px * var(--shadow-size) * var(--shadow-modal-multiplier))
      oklch(from var(--shadow-color) l c h / calc(0.1 * var(--shadow-opacity))); /* dialogs and sheets */
  --shadow-soft: 0 calc(0.75px * var(--shadow-size) * var(--shadow-ambient-multiplier) * var(--shadow-y))
      calc(2px * var(--shadow-size) * var(--shadow-ambient-multiplier))
      calc(-0.75px * var(--shadow-size) * var(--shadow-ambient-multiplier))
      oklch(from var(--shadow-color) l c h / calc(0.03 * var(--shadow-opacity))),
    0 calc(2px * var(--shadow-size) * var(--shadow-ambient-multiplier) * var(--shadow-y))
      calc(5px * var(--shadow-size) * var(--shadow-ambient-multiplier))
      calc(-1.5px * var(--shadow-size) * var(--shadow-ambient-multiplier))
      oklch(from var(--shadow-color) l c h / calc(0.05 * var(--shadow-opacity))),
    0 calc(4.5px * var(--shadow-size) * var(--shadow-ambient-multiplier) * var(--shadow-y))
      calc(12px * var(--shadow-size) * var(--shadow-ambient-multiplier))
      calc(-2.5px * var(--shadow-size) * var(--shadow-ambient-multiplier))
      oklch(from var(--shadow-color) l c h / calc(0.05 * var(--shadow-opacity))); /* ambient lift */

  /* bare `transition*` utilities inherit the themed curve + tempo */
  --default-transition-duration: var(--duration-fast);
  --default-transition-timing-function: var(--ease-standard);
}

@layer base {
  /* v4 defaults border/divide color to currentColor; restore themed border (same rule shadcn v4 ships, host merge is harmless). */
  /* border-box origin too: default padding-box origin + border-box clip + repeat tiles the gradient's far end into a translucent border ring (--border carries alpha in most packs). Escape hatch: bg-origin-padding. */
  *,
  ::after,
  ::before {
    border-color: var(--border);
    background-origin: border-box;
  }

  @supports (corner-shape: squircle) {
    :where([data-control-ui][data-slot]) {
      corner-shape: var(--corner-shape);
    }

  }

  /* Squircle w/o corner-shape support falls back to plain round radius, reading over-rounded; shrink
     fallback by --corner-radius-fit to track Chrome's squircle. Gated on live --corner-shape via style
     query (fires only when squircle selected); re-declared on DA elements since skin-root tokens bake var(--radius) at their root, unreachable by descendant override. No style-query support = current fallback. */
  @supports not (corner-shape: squircle) {
    @container style(--corner-shape: squircle) {
      :where([data-control-ui][data-slot]) {
        /* Halve base control radius; concentric popup/popover tokens re-derive from it, no second factor needed. */
        --radius-control: calc(var(--radius) * 2 * var(--corner-radius-fit));
        --radius-popup-item: calc(var(--radius-control) * 0.6);
        --radius-popup-item-fit: min(var(--radius-popup-item), calc(var(--control-h-xs) / 2));
        --radius-popover: calc(var(--radius-popup-item-fit) + clamp(0px, var(--radius-popup-item-fit) * 1000, var(--popover-padding) - 1px));
        /* Each derives straight from --radius; must mirror the :where([data-skin]) scale above ×fit. */
        --radius-sm: calc(var(--radius) * 0.6 * var(--corner-radius-fit));
        --radius-md: calc(var(--radius) * 0.8 * var(--corner-radius-fit));
        --radius-lg: calc(var(--radius) * var(--corner-radius-fit));
        --radius-xl: calc(var(--radius) * 1.4 * var(--corner-radius-fit));
        --radius-2xl: calc(var(--radius) * 1.6 * var(--corner-radius-fit));
        --radius-field: calc(var(--radius) * 2.2 * var(--corner-radius-fit));
        --radius-panel: calc(var(--radius) * 2.6 * var(--corner-radius-fit));
        --radius-scene: calc(var(--radius) * 2.8 * var(--corner-radius-fit));
      }
    }
  }
}

@layer components {
  :where(
      [data-control-ui="chat-message"][data-slot="root"],
      [data-control-ui="chat-composer"][data-slot="root"]
    ) {
    opacity: 1;
    filter: none;
    translate: 0 0;
    scale: 1;
    transition:
      opacity var(--duration-slow) var(--ease-emphasized),
      filter var(--duration-slow) var(--ease-emphasized),
      translate var(--duration-slow) var(--ease-emphasized),
      scale var(--duration-slow) var(--ease-emphasized);
  }

  @starting-style {
    :where([data-control-ui="chat-message"][data-slot="root"]) {
      opacity: 0;
      filter: blur(8px);
      translate: 0 0.5rem;
      scale: 0.985;
    }

    :where([data-control-ui="chat-composer"][data-slot="root"]) {
      opacity: 0;
      filter: blur(10px);
      translate: 0 0.75rem;
    }
  }






  /* Cross-slide switch, shared by every surface that swaps one panel for another (tabs panels, inline
     citation sources). Contract: the element owning the switch carries data-slide="scope", each swapped
     child data-slide="panel" plus the lifecycle attributes — inert, data-starting-style /
     data-ending-style, data-activation-direction. Base UI stamps those on tabs panels; inline citation
     stamps its own. Keyed on the role, not on a component, so a new caller opts in with two attributes. */
  :where([data-slide="panel"]) {
    translate: 0 0;
    /* No opacity fade: panels unmount, fade-in from 0 would flash empty frame; slide-only keeps content opaque. */
    transition: translate var(--duration-slow) var(--ease-emphasized);
  }

  /* Fallback switch (no anchor positioning): the outgoing panel stays mounted+inert until its exit
     anim finishes; two in-flow panels would stack, so the exiting one is pulled from layout the moment
     it's inert and the entering one gets a soft directional nudge. Active panel is never `inert`. */
  :where([data-slide="panel"][inert]) {
    display: none;
  }

  :where([data-slide="panel"][data-starting-style][data-activation-direction="left"]) {
    translate: -0.35rem 0;
  }

  :where([data-slide="panel"][data-starting-style][data-activation-direction="right"]) {
    translate: 0.35rem 0;
  }

  :where([data-slide="panel"][data-starting-style][data-activation-direction="up"]) {
    translate: 0 -0.35rem;
  }

  :where([data-slide="panel"][data-starting-style][data-activation-direction="down"]) {
    translate: 0 0.35rem;
  }

  /* True cross-slide (anchor positioning, Limited → @supports per the CSS-first rule): the exiting
     panel is revived and glued edge-to-edge onto the entering panel's box (anchor = the open panel).
     Anchor offsets track the anchor's translated box every frame, so the pair travel as ONE strip
     driven by a single transition — the entering panel's ±100% slide — whatever wrapper the panels
     happen to live in (they are not always the scope's direct children). */
  @supports ((anchor-name: --aui-slide-panel) and (anchor-scope: --aui-slide-panel)) {
    /* Per-instance scope: without it the exiting panel would anchor onto the LAST open panel in the
       whole document — another instance's panel. Nested scopes re-scope, so names never leak. */
    :where([data-slide="scope"]) {
      anchor-scope: --aui-slide-panel;
    }

    :where([data-slide="panel"]:not([inert])) {
      anchor-name: --aui-slide-panel;
    }

    /* display:block revives the fallback-hidden panel; anchor-size clips a longer outgoing panel to
       the incoming one's box mid-slide. The per-direction glue below does the placement; a panel with
       direction "none" gets no glue and no hold, i.e. the instant fallback swap. */
    :where([data-slide="panel"][inert][data-ending-style]) {
      display: block;
      position: absolute;
      position-anchor: --aui-slide-panel;
      width: anchor-size(width);
      height: anchor-size(height);
      overflow: clip;
    }

    /* The panels' direct parent turns containing block + crops the ±100% travel while a switch is in
       flight (an absolutely positioned exiting panel escapes the overflow of non-positioned ancestors). */
    :where(:has(> [data-slide="panel"][data-ending-style])) {
      position: relative;
      overflow: clip;
    }

    /* Glue = trailing edge of the strip; the hold animation is what keeps Base UI from unmounting the
       exiting panel mid-slide (it waits on the panel's own animations, and the glue isn't one). */
    :where([data-slide="panel"][inert][data-ending-style][data-activation-direction="left"]) {
      top: anchor(top);
      left: anchor(right);
      animation: aui-slide-exit-hold var(--duration-slow) var(--ease-emphasized) both;
    }

    :where([data-slide="panel"][inert][data-ending-style][data-activation-direction="right"]) {
      top: anchor(top);
      right: anchor(left);
      animation: aui-slide-exit-hold var(--duration-slow) var(--ease-emphasized) both;
    }

    :where([data-slide="panel"][inert][data-ending-style][data-activation-direction="up"]) {
      left: anchor(left);
      top: anchor(bottom);
      animation: aui-slide-exit-hold var(--duration-slow) var(--ease-emphasized) both;
    }

    :where([data-slide="panel"][inert][data-ending-style][data-activation-direction="down"]) {
      left: anchor(left);
      bottom: anchor(top);
      animation: aui-slide-exit-hold var(--duration-slow) var(--ease-emphasized) both;
    }

    :where([data-slide="panel"][data-starting-style][data-activation-direction="left"]) {
      translate: -100% 0;
    }

    :where([data-slide="panel"][data-starting-style][data-activation-direction="right"]) {
      translate: 100% 0;
    }

    :where([data-slide="panel"][data-starting-style][data-activation-direction="up"]) {
      translate: 0 -100%;
    }

    :where([data-slide="panel"][data-starting-style][data-activation-direction="down"]) {
      translate: 0 100%;
    }

    /* Height morph: auto→auto never transitions, so the entering panel starts at the outgoing panel's
       measured height (--aui-slide-prev-height, stamped by the component just before the switch) and
       eases to its own intrinsic height — calc-size() makes the auto endpoint interpolable. The glued
       exiting panel follows via anchor-size(height), so the whole strip resizes as one; overflow
       mid-morph is cropped by the parent clip already active for the slide. :not([inert]) keeps this
       off the exiting panel, whose height must stay anchor-size(height). */
    @supports (height: calc-size(auto, size)) {
      :where([data-slide="panel"]:not([inert])) {
        height: calc-size(auto, size);
        transition: translate var(--duration-slow) var(--ease-emphasized), height var(--duration-slow) var(--ease-emphasized);
      }

      :where([data-slide="panel"][data-starting-style]) {
        height: var(--aui-slide-prev-height, calc-size(auto, size));
      }
    }
  }

  /* Visually inert 0.999→1 hold: exists purely so the exiting panel reports a running animation for
     the slide's duration. Rides the motion tokens, so reduced motion collapses it to an instant swap. */
  @keyframes aui-slide-exit-hold {
    from {
      opacity: 0.999;
    }
    to {
      opacity: 1;
    }
  }

}
